def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated strip gives the colors in top-to-bottom order.
    strip = None
    for r in range(h):
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        if end - r >= 2:
            cols = [c for c, v in enumerate(grid[r]) if v]
            if len(cols) > 1 and cols == list(range(cols[0], cols[-1] + 1)):
                seq = grid[r][cols[0]:cols[-1] + 1]
                if len(set(seq)) > 1:
                    strip = (r, end, cols[0], cols[-1] + 1, seq)
                    break

    if strip is None:
        return [row[:] for row in grid]

    sr, se, sc, ec, seq = strip
    strip_cells = {(r, c) for r in range(sr, se) for c in range(sc, ec)}

    # Find the component colored 1; diagonal contact is part of the shape.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in strip_cells or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in strip_cells and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            components.append((color, comp))

    anchor = [comp for color, comp in components if color == 1]
    if not anchor:
        return [row[:] for row in grid]
    comp = max(anchor, key=len)
    top, left = min(y for y, x in comp), min(x for y, x in comp)
    pattern = [(y - top, x - left) for y, x in comp]
    shape_h = max(dy for dy, dx in pattern) + 1
    index = seq.index(1)
    start_y = top - index * shape_h

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(seq):
        y0 = start_y + i * shape_h
        for dy, dx in pattern:
            y, x = y0 + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
